class DomainError extends Error {constructor(message,status=400){super(message);this.status=status}}
const rupees=n=>'₹'+(n/100).toLocaleString('en-IN',{minimumFractionDigits:2});
const today=(now=new Date())=>now.toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});
